    """
    Transform: For each row, scan for consecutive 3s and surrounding 9s.
    When we find a pattern, replace:
    - 3 stays as 3
    - 9s between consecutive 3s become 2
    - 9s before first 3 of the group become 1
    - 9s after last 3 of the group become 1
    - Only keep one group of alternating 3s/2s per row
    """
    result = g.copy().astype(int)
    n_rows, n_cols = result.shape

    for r in range(n_rows):
        # Find all 3s in this row
        pos_3 = [c for c in range(n_cols) if result[r, c] == 3]

        if len(pos_3) == 0:
            continue  # No 3s, leave row as is (should be all 9s or pattern matched already)

        # Check if we can form a contiguous group
        # Pattern should be: 3, 9, 3, 9, 3, 9, ..., 3 (alternating)
        if len(pos_3) < 2:
            continue  # Need at least 2 consecutive 3s with 9s between

        # Check if all 9s between consecutive 3s are present
        valid_group = True
        for i in range(len(pos_3) - 1):
            gap = pos_3[i+1] - pos_3[i]
            if gap != 2:  # Should be exactly 2 (one 9 between)
                valid_group = False
                break

        if not valid_group:
            # Try to find a valid group among the 3s
            # Look for a subsequence of 3s that are spaced by 2 (one 9 between)
            found_valid = False
            for i in range(len(pos_3) - 1):
                subpos = pos_3[i:]
                valid = True
                for j in range(len(subpos) - 1):
