                            result[r, c] = 1
                    for i, c in enumerate(subpos):
                        if c < last_3:
                            next_c = c + 1
                            result[r, next_c] = 2
                    found_valid = True
                    break
            if found_valid:
                continue

        if len(pos_3) < 2:
            continue

        # All 3s form a valid alternating pattern
        for i, c in enumerate(pos_3):
            if i < len(pos_3) - 1:  # Not the last one
                next_c = c + 1
                result[r, next_c] = 2
            else:  # Last one
                pass  # stays as 3

    return result

